<?php require_once __DIR__.'/../config/auth.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$active=db()->prepare("SELECT COUNT(*) FROM emprestimos WHERE livro_id=?");$active->execute([$id]);if($active->fetchColumn())flash('error','Este livro possui empréstimos registrados (ativos ou no histórico) e não pode ser excluído.');else{try{db()->prepare('DELETE FROM livros WHERE id=?')->execute([$id]);flash('success','Livro excluído.');}catch(PDOException $e){flash('error','Não foi possível excluir este livro.');}}redirect('admin/livros.php');}$q=trim($_GET['q']??'');$s=db()->prepare('SELECT * FROM livros WHERE titulo LIKE ? OR autor LIKE ? OR codigo_barras LIKE ? ORDER BY titulo');$s->execute(array_fill(0,3,'%'.$q.'%'));$books=$s->fetchAll();$pageTitle='Gerenciar livros';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><div class="filterbar"><div class="searchbar"><form><input name="q" value="<?=e($q)?>" placeholder="Buscar por título, autor ou código"></form></div><a class="btn btn-small" href="<?=base_url('admin/cadastrar-livro.php')?>">+ Novo livro</a></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Capa</th><th>Código</th><th>Título</th><th>Autor</th><th>Categoria</th><th>Qtd.</th><th>Disponíveis</th><th>Ações</th></tr></thead><tbody><?php foreach($books as $l):?><tr><td><?php if($l['capa']):?><img class="mini-cover" src="<?=base_url('assets/uploads/capas/'.$l['capa'])?>" alt=""><?php endif;?></td><td><?=e($l['codigo_barras'])?></td><td><b><?=e($l['titulo'])?></b></td><td><?=e($l['autor'])?></td><td><?=e($l['categoria'])?></td><td><?=$l['quantidade']?></td><td><?=$l['quantidade_disponivel']?></td><td><a class="btn btn-small btn-outline" href="<?=base_url('admin/editar-livro.php?id='.(int)$l['id'])?>">Editar</a> <form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=$l['id']?>"><button class="btn btn-small btn-danger" data-confirm="Excluir este livro?">Excluir</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/dashboard-footer.php';?>
